## Why This Is Asked

Tests the ability to extend behavior without changing core ingestion logic using a registry/strategy pattern. Evaluates how to design minimal, pluggable interfaces that can be wired via dependency injection and dynamically discovered at runtime.

## Key Concepts

- Registry/Strategy pattern for pluggable parsers
- Stateless parsers and dynamic registration
- Error handling for unknown formats and partial parses
- Thread-safety and DI considerations

## Code Example

```javascript
export interface Parser {
  parse(line: string): any
}

export class JsonlParser implements Parser {
  parse(line: string) { return JSON.parse(line) }
}

export class CsvParser implements Parser {
  parse(line: string) { /* simple split */ return line.split(',') }
}

export class ParserRegistry {
  private map = new Map<string, Parser>();
  register(format: string, p: Parser) { this.map.set(format, p) }
  get(format: string): Parser {
    const p = this.map.get(format)
    if (!p) throw new Error(`Unknown format: ${format}`)
    return p
  }
}
```

